    aTime1: '',
    aDown:'',
    bTime1: '',
    bDown:'',
    cTime1: '',
    cDown:'',
    dTime1: '',
    dDown:'',
    eTime1: '',
    eDown:'',
    autoAddFlag:2,
    autoOpenFlag:2,
    autoOpenTime:'',
}) 
const rules = ref({
    period: [
        {required: true, message: '请填写期数', trigger: 'blur'}
    ],
    openTimeDay: [
        {required: true, message: '开奖时间不能为空', trigger: 'blur'}
    ],
    beginTime1: [
        {required: true, message: '开盘时间不能为空', trigger: 'blur'}
    ],
    endTime1: [
        {required: true, message: '开盘时间不能为空', trigger: 'blur'}
    ]
})
const num = ref(3)
const tits = ref('游戏开奖')
const loading = ref(false)
const props = defineProps(['id'])
const dtime = ref([])
const logInfo = ref('')
const selectedValues = ref(['00', '00', '00'])
onMounted(() => {
    let ust = JSON.parse(localStorage.getItem('userInfo'))
    logInfo.value = ust
    getOpens();
})
const getTimes = () => {
    showStart.value = true;
    if(ruleForm.value.openTimeDay){
      const date = new Date(ruleForm.value.openTimeDay)
      dtime.value = [date.getFullYear(), date.getMonth() + 1, date.getDate()]
    }else{
       const date = new Date()
       dtime.value = [date.getFullYear(), date.getMonth() + 1, date.getDate()]  
    }  
}
const selectTime = (val) =>{
    seles.value = val;
    showTime.value  = true;
    const parts = ruleForm.value[val].split(':')
    selectedValues.value = parts.length === 3 ? parts : ['00', '00', '00']  
}

const conTimeTab = () =>{
    ruleForm.value[seles.value] = selectedValues.value.join(':');
    cancelTime()
}
const cancelTime = () =>{
    showTime.value = false;  
}
const confirmTime = (val, field) => {
    ruleForm.value.openTimeDay = val.selectedValues[0]+'-'+val.selectedValues[1]+'-'+val.selectedValues[2]
    dtime.value = val.selectedValues
    showStart.value = false
}
const check_count = (obj) =>{
    let iten;
    for(iten in reads.value){
        if(reads.value[obj]===reads.value[iten]&&obj!==iten){
            type.value = obj;
            reads.value[obj] = '';
            showToast('当前输入值与其他值重复值');
            break;
        }else{
            type.value='';
        }
    }
}
const kjchek = async() =>{
    if(ruleForm.value.autoAddFlag==1){
        try {
            const res = await userStore.chackOpenmkFlag(openList.value.lotteryId);
            ruleForm.value.autoAddFlag = 2;
            showToast('设置自动添加下一期需没有超过当天的期号')
        } catch (error) {
            console.log('校验失败')
        }
    }
}
const getOpens = async() =>{
    try {
        const res = await userStore.getMkOpenInfo(props.id);
        openList.value = res.data; 
        let obj = res.data;
        let numlist = obj.result?obj.result.split(','):'';
        if(numlist.length>0){
            reads.value.v1 = numlist[0];
            reads.value.v2 = numlist[1];
            reads.value.v3 = numlist[2];
            reads.value.v4 = numlist[3];
            reads.value.v5 = numlist[4];
            reads.value.v6 = numlist[5];
            reads.value.v7 = numlist[6];
        }
        ruleForm.value = {
            period: obj.period,
            openTimeDay: userTime.dateNow(obj.openTimeDay),
            beginTime1: obj.beginTime?userTime.timelist(obj.beginTime):'',
            type: obj.type?obj.type:1,
            endTime1: obj.endTime?userTime.timelist(obj.endTime):'',
            openTime1: obj.ftmEndTime?userTime.timelist(obj.ftmEndTime):'',
            aTime1: obj.atime?userTime.timelist(obj.atime):'',
            adown:obj.adown,
            bTime1: obj.btime?userTime.timelist(obj.btime):'',
            bdown:obj.bdown,
            cTime1: obj.ctime?userTime.timelist(obj.ctime):'',
            cdown:obj.cdown,
            dTime1: obj.dtime?userTime.timelist(obj.dtime):'',
            ddown:obj.ddown,
            eTime1: obj.etime?userTime.timelist(obj.etime):'',
            edown:obj.edown,
            autoAddFlag:obj.autoAddFlag,
            autoOpenFlag:obj.autoOpenFlag,
            autoOpenTime:obj.autoOpenTime?userTime.timelist(obj.autoOpenTime):'',
        }
    } catch (error) {
        console.log('获取用户信息失败')
    }
}
const submitForm = async () => {
    if (loading.value) return
    try {
        await addsubaccount()
    } catch (error) {
        console.log('表单验证失败')
    }
}
const addsubaccount = async (data) => {
    loading.value = true;
    let str = '';
    if(ruleForm.value.type==1){
        str = {
            id:props.id,
            type:ruleForm.value.type,
            period: ruleForm.value.period,
            openTimeDay: ruleForm.value.openTimeDay+' '+'00:00:00',
            beginTime:ruleForm.value.openTimeDay+' '+ruleForm.value.beginTime1,
            endTime:ruleForm.value.openTimeDay+' '+ruleForm.value.endTime1,
            ftmEndTime:ruleForm.value.openTime1?(ruleForm.value.openTimeDay+' '+ruleForm.value.openTime1):'',
            autoAddFlag:ruleForm.value.autoAddFlag,
            autoOpenFlag:ruleForm.value.autoOpenFlag,
            autoOpenTime:ruleForm.value.autoOpenTime?(ruleForm.value.openTimeDay+' '+ruleForm.value.autoOpenTime):'',
        };
    }else{
        str = {
            id:props.id,
            period: ruleForm.value.period,
            type:ruleForm.value.type,
            openTimeDay: ruleForm.value.openTimeDay+' '+'00:00:00',
            beginTime:ruleForm.value.openTimeDay+' '+ruleForm.value.beginTime1,
            endTime:ruleForm.value.openTimeDay+' '+ruleForm.value.endTime1,
            ftmEndTime:ruleForm.value.openTime1?ruleForm.value.openTimeDay+' '+ruleForm.value.openTime1:'',
            atime: ruleForm.value.aTime1?(ruleForm.value.openTimeDay+' '+ruleForm.value.aTime1):'',
            adown:ruleForm.value.adown,
            btime: ruleForm.value.bTime1?(ruleForm.value.openTimeDay+' '+ruleForm.value.bTime1):'',
            bdown:ruleForm.value.bdown,
            ctime: ruleForm.value.cTime1?(ruleForm.value.openTimeDay+' '+ruleForm.value.cTime1):'',
            cdown:ruleForm.value.cdown,
            dtime: ruleForm.value.dTime1?(ruleForm.value.openTimeDay+' '+ruleForm.value.dTime1):'',
            ddown:ruleForm.value.ddown,
            etime: ruleForm.value.eTime1?(ruleForm.value.openTimeDay+' '+ruleForm.value.eTime1):'',
            edown:ruleForm.value.edown,
            autoAddFlag:ruleForm.value.autoAddFlag,
            autoOpenFlag:ruleForm.value.autoOpenFlag,
            autoOpenTime:ruleForm.value.autoOpenTime?(ruleForm.value.openTimeDay+' '+ruleForm.value.autoOpenTime):'',
        };
    }
    try {
        const res = await userStore.updateMkOpen(str);
        showToast('修改成功')
        router.push({
            path: '/lotMkHistory'
        })
    } catch (error) {
        loading.value = false;
        console.log('获取用户信息失败')
    } finally {
        loading.value = false;
    }
}
const issueSub = async() =>{
    let str1 = '';
    let str = {
        id:props.id,
        result:''
    }
    let iten;
    for(iten in reads.value){
        if(!reads.value[iten]&&reads.value[iten]!=0){
            str1 = 1;
            break;
        }
        str.result += reads.value[iten]+',';
    }
    if(str1){
        showToast('当前输入有空值不能提交')
        return;
    }
    str.result=str.result.substring(0,str.result.length-1);
    try {
        await showConfirmDialog({
            title: '当前输入开奖码分别为'+str.result+'确认是否开奖',
            messageAlign: 'center',  // 设置 message 居中
            width: '85vw',  
        })
        const loadds = showLoadingToast({
            lock: true,
            duration: 0,
            forbidClick: true,
            mask: true,
            background: 'rgba(0, 0, 0, 0.7)',
            message: '正在开奖中，请稍等...'
        })
        const res = await userStore.pmkopen(str);
        showToast(res.data)
        loadds.close();
        router.push({
            path: '/lotMkHistory'
        })
    } catch (error) {
        if (error !== 'cancel' && error !== 'close') {
          console.error('重置密码失败:', error)
        }
    } finally {
       // loadds.close();
    }
}
