        if(!reads.value[iten]){
            str1 = 1;
            break;
        }
        str.result += reads.value[iten]+',';
    }
    if(str1){
        showToast('当前输入有空值不能提交')
        return;
    }
    if(logInfo.value.role==1){
        str.account = account.value;
    }
    str.result=str.result.substring(0,str.result.length-1);
    try {
        await showConfirmDialog({
            title: '当前开奖码分别为'+str.result+'确认是否重新结算',
